// Atlas: ID a texty EN/CS (prototyp A1). Vzor pro src/atlas-content.js a slovníky src/locales/ (přenáší vývojář A2/B1, tabulka v research/atlas/03-texty.md).
// Texty jsou ploché i18n klíče (TEXTS.en / TEXTS.cs, stejné klíče a parametry), struktury níže je čtou gettery, takže se mění s jazykem (jako scenes.js).
// Plurál = objekt {one,other} v EN, {one,few,many,other} v CS, vybírá ho params.count. Bez laditelných čísel: hodnoty dosazuje numbers.js do {tokenů}.
// Šablona účinku: effect = pole vět, text v klíči bonus.<id>.effect.<k>; věta {if:'klíč'} se ukáže, jen když má úroveň hodnotu klíče (pravdivou).
// Jednotky tokenů (units): '+%' → "+10 %", '%' → "25 %", 'x' → "×4", 'm' → "1.5 m", 's' → "0.6 s", 'times' → "1 time / 2 times", 'count' → "once / twice / 3 times".

let lang = 'en';
export const LANGS = ['en', 'cs'];
export const getLang = () => lang;
export const setLang = id => (lang = Object.hasOwn(TEXTS, id) ? id : 'en');
// syrový text (bez dosazení): aktuální jazyk, pak EN, jinak undefined
export const tx = (key, id = lang) => TEXTS[id]?.[key] ?? TEXTS.en[key];
const loc = (o, prefix, fields) => {
  for (const f of fields)
    Object.defineProperty(o, f, { get: () => tx(`${prefix}.${f}`), enumerable: true });
  return o;
};

export const DISTRICTS = [
  { id: 'violet', character: { id: 'bolts' } },
  { id: 'docks', character: { id: 'marge' } },
  { id: 'horizon', character: { id: 'stella' } },
  { id: 'core', character: { id: 'zippy' } },
].map(d => {
  const c = d.character;
  loc(d, `district.${d.id}`, ['name', 'frame']);
  loc(c, `character.${c.id}`, ['name', 'role']);
  Object.defineProperty(c, 'lines', {
    get: () => [1, 2, 3].map(k => tx(`character.${c.id}.line${k}`)),
    enumerable: true,
  });
  d.locals = loc({}, `district.${d.id}`, ['bird', 'gust']);
  return d;
});

